/**
 * Tool registry types (design D3, contracts §35). Every operation of `docs/api/openapi.json` is
 * classified: a tool record (`OperationTool`, enabled or planned for a later phase) or a
 * `NotApplicableOperation` with a reason. Records are generated by
 * `scripts/generate-registry.ts` into `operations.generated.ts`; nothing here is hand-written per
 * operation except the manifest's rules and overrides.
 */

export const PROGRAM_PHASES = ['AI-1', 'AI-2', 'AI-3', 'AI-4', 'AI-5', 'AI-6'] as const;
export type ProgramPhase = (typeof PROGRAM_PHASES)[number];

export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
export type ToolAccess = 'read' | 'write';
export const TOOL_RISKS = ['read', 'read_audited', 'low', 'medium', 'high', 'critical'] as const;
export type ToolRisk = (typeof TOOL_RISKS)[number];
export type ToolConfirm = 'none' | 'confirm' | 'confirm+impact' | 'confirm+impact+reauth';
export type MatrixStatus = 'IMPLEMENTED' | 'PARTIALLY_IMPLEMENTED' | 'MISSING' | 'NOT_APPLICABLE';

/** Copy of the operation's `x-eg-permissions` (`authenticated` when the operation has none). */
export type PermissionRequirement =
  | { mode: 'all'; permissions: string[] }
  | { mode: 'any'; permissions: string[] }
  | { mode: 'authenticated' };

/** Fills a parameter the model may omit (D5 step 4). */
export type ParamBinding = 'self_organization';

/** Card and ref hints (D8). */
export interface DisplayHints {
  /** Card title (default: the operation summary). */
  title?: string;
  /** Table / key-value columns in order (default: the first scalar fields). */
  columns?: string[];
  /** Field holding the row's public id for refs and links (default: `id`, `publicId`, `<x>Id`). */
  refField?: string;
  /** Row field that fills the portal route of a table row (default: the ref id). */
  linkField?: string;
  /** Resource type stored with a ref (default: derived from the portal route or the tool). */
  resourceType?: string;
}

export interface OperationTool {
  /** `snake(controller) + '_' + snake(method)`, `^[a-z0-9_]{1,64}$`, unique. */
  name: string;
  operationId: string;
  method: HttpMethod;
  /** Full OpenAPI path including the `/api/v1` prefix (the loopback path). */
  pathTemplate: string;
  /** OpenAPI tags joined with `,` (e.g. `archive,journaling`). */
  module: string;
  summary: string;
  /** Summary and description, trimmed to 300 characters. */
  description: string;
  /** JSON Schema object: path + query parameters (+ `body` when the operation takes one). */
  inputSchema: Record<string, unknown>;
  pathParams: string[];
  queryParams: string[];
  /** Whether `inputSchema.properties.body` is the JSON request body. */
  hasBody: boolean;
  requirement: PermissionRequirement;
  /** Every permission of the requirement is `platform:*` (absent for customer users). */
  platformOnly: boolean;
  idempotency: 'required' | 'legacy' | null;
  rateClass: 'sensitive' | 'expensive' | null;
  cursor: 'v0' | 'v1' | null;
  access: ToolAccess;
  risk: ToolRisk;
  confirm: ToolConfirm;
  phase: ProgramPhase;
  enabled: boolean;
  status: Exclude<MatrixStatus, 'NOT_APPLICABLE'>;
  /** Portal deep-link template (Appendix B), e.g. `/policies/{policyId}`. */
  portalRoute: string | null;
  /** Portal pages that call this operation (from `apps/admin-portal/src/features/**`). */
  portalPages: string[];
  display: DisplayHints;
  /** Response paths (`data[].subject`, `headers[].value`) holding mail-derived or attacker text. */
  untrustedFields: string[];
  bind: Record<string, ParamBinding>;
  limitations: string | null;
  testedBy: string | null;
}

export interface NotApplicableOperation {
  operationId: string;
  method: HttpMethod;
  pathTemplate: string;
  module: string;
  summary: string;
  requirement: PermissionRequirement;
  access: ToolAccess;
  /** `critical` for portal-only critical actions, else null. */
  risk: 'critical' | null;
  reason: string;
  portalRoute: string | null;
  portalPages: string[];
}

/** Per-operation manifest override (D3). */
export interface OperationOverride {
  status?: 'not_applicable';
  reason?: string;
  risk?: ToolRisk;
  phase?: ProgramPhase;
  title?: string;
  description?: string;
  portalRoute?: string;
  display?: DisplayHints;
  untrustedFields?: string[];
  bind?: Record<string, ParamBinding>;
  limitations?: string;
  testedBy?: string;
}
